namespace RoomBooking.Domain.Entities;

public class RecurringSeries { public int Id { get; set; } public int CompanyId { get; set; } public int RoomId { get; set; } public int OrganizerUserId { get; set; } public string Title { get; set; } = ""; public string RecurrenceRule { get; set; } = ""; public DateTime SeriesStart { get; set; } public DateTime SeriesEnd { get; set; } public string Status { get; set; } = "Active"; public ICollection<Reservation> Reservations { get; set; } = []; }
public class ReservationApproval { public int Id { get; set; } public int ReservationId { get; set; } public int ApproverUserId { get; set; } public string Status { get; set; } = "Pending"; public string Reason { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public Reservation? Reservation { get; set; } public User? Approver { get; set; } }
public class ReservationAttendee { public int Id { get; set; } public int ReservationId { get; set; } public int? UserId { get; set; } public string Email { get; set; } = ""; public string Name { get; set; } = ""; public string ResponseStatus { get; set; } = "Pending"; public Reservation? Reservation { get; set; } }
